=== Makefile ===
# 内核模块 Makefile

# 模块名称
obj-m += softirq_collector.o
obj-m += cpu_stat_collector.o

# 内核源码路径
KDIR ?= /lib/modules/$(shell uname -r)/build

# 当前目录
PWD := $(shell pwd)

# 默认目标：编译模块
all:
	$(MAKE) -C $(KDIR) M=$(PWD) modules

# 清理
clean:
	$(MAKE) -C $(KDIR) M=$(PWD) clean

# 安装所有模块
install: install-softirq install-cpustat

# 安装软中断模块
install-softirq:
	sudo insmod softirq_collector.ko
	@echo "Module loaded. Device: /dev/cpu_softirq_monitor"

# 安装 CPU 状态模块
install-cpustat:
	sudo insmod cpu_stat_collector.ko
	@echo "Module loaded. Device: /dev/cpu_stat_monitor"

# 卸载所有模块
uninstall: uninstall-softirq uninstall-cpustat

# 卸载软中断模块
uninstall-softirq:
	-sudo rmmod softirq_collector
	@echo "softirq_collector module unloaded."

# 卸载 CPU 状态模块
uninstall-cpustat:
	-sudo rmmod cpu_stat_collector
	@echo "cpu_stat_collector module unloaded."

# 查看模块信息
info:
	modinfo softirq_collector.ko
	modinfo cpu_stat_collector.ko

# 查看内核日志
log:
	sudo dmesg | tail -30

.PHONY: all clean install install-softirq install-cpustat uninstall uninstall-softirq uninstall-cpustat info log

=== softirq_collector SEC/struct ===
/*
 * softirq_collector.c - 软中断统计数据采集内核模块
 *
 * 功能：
 * 1. 在内核空间分配结构体数组内存，存放所有 CPU 的软中断统计数据
 * 2. 使用高精度定时器每秒从 kstat_softirqs 读取数据并更新
 * 3. 注册字符设备 /dev/cpu_softirq_monitor，通过 mmap 暴露给用户空间
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/device.h>
#include <linux/mm.h>
#include <linux/slab.h>
#include <linux/hrtimer.h>
#include <linux/ktime.h>
#include <linux/interrupt.h>
#include <linux/kernel_stat.h>
#include <linux/cpumask.h>
#include <linux/version.h>
#include <asm/io.h>

#define DEVICE_NAME "cpu_softirq_monitor"
#define CLASS_NAME  "softirq_monitor"
#define MAX_CPUS    256

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Monitor System");
MODULE_DESCRIPTION("Softirq statistics collector via mmap");
MODULE_VERSION("1.0");

/* 软中断统计结构体 - 与用户空间共享 */
struct softirq_stat {
    char cpu_name[16];      /* CPU 名称，如 "cpu0" */
    uint64_t hi;            /* HI_SOFTIRQ */
    uint64_t timer;         /* TIMER_SOFTIRQ */
    uint64_t net_tx;        /* NET_TX_SOFTIRQ */
    uint64_t net_rx;        /* NET_RX_SOFTIRQ */
    uint64_t block;         /* BLOCK_SOFTIRQ */
    uint64_t irq_poll;      /* IRQ_POLL_SOFTIRQ */
    uint64_t tasklet;       /* TASKLET_SOFTIRQ */
    uint64_t sched;         /* SCHED_SOFTIRQ */
    uint64_t hrtimer;       /* HRTIMER_SOFTIRQ */
    uint64_t rcu;           /* RCU_SOFTIRQ */
};

/* 全局变量 */
static dev_t dev_num;
static struct cdev softirq_cdev;
static struct class *softirq_class;
static struct device *softirq_device;

static struct softirq_stat *softirq_data;   /* 共享内存区域 */
static unsigned long data_size;              /* 数据区大小 */
static int num_cpus;                         /* CPU 数量 */

static struct hrtimer update_timer;          /* 高精度定时器 */

