1	/*
2	 * cpu_stat_collector.c - CPU 状态统计数据采集内核模块
3	 *
4	 * 功能：
5	 * 1. 在内核空间分配结构体数组内存，存放所有 CPU 的状态统计数据
6	 * 2. 使用高精度定时器每秒从 per_cpu(kstat_cpu, cpu).cpustat[] 读取数据并更新
7	 * 3. 注册字符设备 /dev/cpu_stat_monitor，通过 mmap 暴露给用户空间
8	 *
9	 * 数据来源：
10	 * - Linux 内核中每个 CPU 都有一个 struct kernel_cpustat 类型的 per-CPU 变量
11	 * - 该结构体中的 cpustat[] 数组记录 CPU 在不同状态下的累计时间
12	 * - 状态包括：user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice
13	 */
14	
15	#include <linux/module.h>
16	#include <linux/kernel.h>
17	#include <linux/init.h>
18	#include <linux/fs.h>
19	#include <linux/cdev.h>
20	#include <linux/device.h>
21	#include <linux/mm.h>
