32	#define CLASS_NAME  "cpu_stat_monitor"
33	#define MAX_CPUS    256
34	
35	/* 将纳秒转换为 jiffies（clock_t）- 内联实现 */
36	static inline u64 nsec_to_jiffies(u64 nsec)
37	{
38	    return div_u64(nsec, NSEC_PER_SEC / HZ);
39	}
40	
41	MODULE_LICENSE("GPL");
42	MODULE_AUTHOR("Monitor System");
43	MODULE_DESCRIPTION("CPU statistics collector via mmap");
44	MODULE_VERSION("1.0");
45	
46	/* CPU 状态统计结构体 - 与用户空间共享 */
47	struct cpu_stat {
48	    char cpu_name[16];      /* CPU 名称，如 "cpu0" */
49	    uint64_t user;          /* 用户态时间 */
50	    uint64_t nice;          /* 低优先级用户态时间 */
51	    uint64_t system;        /* 内核态时间 */
52	    uint64_t idle;          /* 空闲时间 */
53	    uint64_t iowait;        /* I/O 等待时间 */
54	    uint64_t irq;           /* 硬中断时间 */
55	    uint64_t softirq;       /* 软中断时间 */
56	    uint64_t steal;         /* 虚拟化偷取时间 */
57	    uint64_t guest;         /* 虚拟机运行时间 */
58	    uint64_t guest_nice;    /* 低优先级虚拟机运行时间 */
59	};
60	
61	/* 全局变量 */
62	static dev_t dev_num;
63	static struct cdev cpu_stat_cdev;
64	static struct class *cpu_stat_class;
65	static struct device *cpu_stat_device;
