73	
74	/*
75	 * 获取 CPU 空闲时间
76	 * 需要考虑 NO_HZ 模式下的空闲时间统计
77	 */
78	static u64 cpu_stat_get_idle_time(int cpu)
79	{
80	    u64 idle_time = -1ULL;
81	
82	    /* 尝试获取精确的空闲时间（考虑 tickless 模式） */
83	    idle_time = get_cpu_idle_time_us(cpu, NULL);
84	
85	    if (idle_time == -1ULL) {
86	        /* 回退到传统方式 */
87	        idle_time = kcpustat_cpu(cpu).cpustat[CPUTIME_IDLE];
88	        idle_time = nsec_to_jiffies(idle_time);
89	    } else {
90	        /* 转换微秒到 clock_t */
91	        idle_time = usecs_to_jiffies(idle_time);
92	    }
93	
94	    return idle_time;
95	}
96	
97	/*
98	 * 获取 CPU I/O 等待时间
99	 * 需要考虑 NO_HZ 模式下的 iowait 时间统计
100	 */
101	static u64 cpu_stat_get_iowait_time(int cpu)
102	{
103	    u64 iowait_time = -1ULL;
104	
105	    /* 尝试获取精确的 iowait 时间（考虑 tickless 模式） */
106	    iowait_time = get_cpu_iowait_time_us(cpu, NULL);
107	
108	    if (iowait_time == -1ULL) {
109	        /* 回退到传统方式 */
110	        iowait_time = kcpustat_cpu(cpu).cpustat[CPUTIME_IOWAIT];
111	        iowait_time = nsec_to_jiffies(iowait_time);
112	    } else {
113	        /* 转换微秒到 clock_t */
114	        iowait_time = usecs_to_jiffies(iowait_time);
115	    }
116	
117	    return iowait_time;
118	}
