120	/*
121	 * 更新 CPU 状态统计数据
122	 * 从内核的 kcpustat_cpu 读取数据并填充到共享内存
123	 */
124	static void update_cpu_stats(void)
125	{
126	    int cpu;
127	    int idx = 0;
128	    struct kernel_cpustat *kcs;
129	
130	    for_each_possible_cpu(cpu) {
131	        if (idx >= MAX_CPUS)
132	            break;
133	
134	        kcs = &kcpustat_cpu(cpu);
135	
136	        snprintf(cpu_stat_data[idx].cpu_name, 
137	                 sizeof(cpu_stat_data[idx].cpu_name), 
138	                 "cpu%d", cpu);
139	
140	        /* 读取各类 CPU 时间统计（单位：纳秒转换为 jiffies） */
141	        cpu_stat_data[idx].user = nsec_to_jiffies(kcs->cpustat[CPUTIME_USER]);
142	        cpu_stat_data[idx].nice = nsec_to_jiffies(kcs->cpustat[CPUTIME_NICE]);
143	        cpu_stat_data[idx].system = nsec_to_jiffies(kcs->cpustat[CPUTIME_SYSTEM]);
144	        cpu_stat_data[idx].idle = cpu_stat_get_idle_time(cpu);
145	        cpu_stat_data[idx].iowait = cpu_stat_get_iowait_time(cpu);
146	        cpu_stat_data[idx].irq = nsec_to_jiffies(kcs->cpustat[CPUTIME_IRQ]);
147	        cpu_stat_data[idx].softirq = nsec_to_jiffies(kcs->cpustat[CPUTIME_SOFTIRQ]);
148	        cpu_stat_data[idx].steal = nsec_to_jiffies(kcs->cpustat[CPUTIME_STEAL]);
149	        cpu_stat_data[idx].guest = nsec_to_jiffies(kcs->cpustat[CPUTIME_GUEST]);
150	        cpu_stat_data[idx].guest_nice = nsec_to_jiffies(kcs->cpustat[CPUTIME_GUEST_NICE]);
151	
152	        idx++;
153	    }
154	
155	    /* 标记结束 */
156	    if (idx < MAX_CPUS) {
157	        cpu_stat_data[idx].cpu_name[0] = '\0';
158	    }
159	}
160	
161	/*
162	 * 高精度定时器回调函数
163	 * 每秒触发一次，更新 CPU 状态统计数据
164	 */
165	static enum hrtimer_restart timer_callback(struct hrtimer *timer)
166	{
167	    update_cpu_stats();
168	    
169	    /* 重新启动定时器 */
170	    hrtimer_forward_now(timer, timer_interval);
171	    return HRTIMER_RESTART;
172	}
173	
174	/*
175	 * 设备打开回调
176	 */
177	static int cpu_stat_open(struct inode *inode, struct file *file)
178	{
179	    pr_info("%s: device opened\n", DEVICE_NAME);
180	    return 0;
181	}
182	
183	/*
184	 * 设备关闭回调
185	 */
186	static int cpu_stat_release(struct inode *inode, struct file *file)
187	{
188	    pr_info("%s: device closed\n", DEVICE_NAME);
189	    return 0;
190	}
191	
192	/*
193	 * mmap 回调 - 将内核数据映射到用户空间
194	 */
195	static int cpu_stat_mmap(struct file *file, struct vm_area_struct *vma)
196	{
197	    unsigned long size = vma->vm_end - vma->vm_start;
198	    unsigned long pfn;
199	    int ret;
200	
201	    /* 检查映射大小 */
202	    if (size > data_size) {
203	        pr_err("%s: mmap size %lu exceeds data size %lu\n", 
204	               DEVICE_NAME, size, data_size);
205	        return -EINVAL;
206	    }
207	
208	    /* 设置页面属性为不可缓存，确保数据一致性 */
209	    vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
210	
211	    /* 获取物理页帧号 */
212	    pfn = page_to_pfn(virt_to_page(cpu_stat_data));
213	
214	    /* 建立映射 */
215	    ret = remap_pfn_range(vma, vma->vm_start, pfn, size, vma->vm_page_prot);
216	    if (ret) {
217	        pr_err("%s: remap_pfn_range failed: %d\n", DEVICE_NAME, ret);
218	        return ret;
219	    }
220	
221	    pr_info("%s: mmap successful, size=%lu\n", DEVICE_NAME, size);
222	    return 0;
223	}
224	
225	/* 文件操作结构体 */
226	static const struct file_operations cpu_stat_fops = {
227	    .owner   = THIS_MODULE,
228	    .open    = cpu_stat_open,
229	    .release = cpu_stat_release,
230	    .mmap    = cpu_stat_mmap,
231	};
