235	 * 模块初始化
236	 */
237	static int __init cpu_stat_collector_init(void)
238	{
239	    int ret;
240	
241	    pr_info("%s: initializing module\n", DEVICE_NAME);
242	
243	    /* 获取 CPU 数量 */
244	    num_cpus = num_possible_cpus();
245	    if (num_cpus > MAX_CPUS)
246	        num_cpus = MAX_CPUS;
247	
248	    pr_info("%s: detected %d CPUs\n", DEVICE_NAME, num_cpus);
249	
250	    /* 分配共享内存 - 使用 PAGE_SIZE 对齐以支持 mmap */
251	    data_size = PAGE_ALIGN(sizeof(struct cpu_stat) * MAX_CPUS);
252	    cpu_stat_data = (struct cpu_stat *)__get_free_pages(GFP_KERNEL | __GFP_ZERO,
253	                                                        get_order(data_size));
254	    if (!cpu_stat_data) {
255	        pr_err("%s: failed to allocate memory\n", DEVICE_NAME);
256	        return -ENOMEM;
257	    }
258	
259	    pr_info("%s: allocated %lu bytes for data\n", DEVICE_NAME, data_size);
260	
261	    /* 分配设备号 */
262	    ret = alloc_chrdev_region(&dev_num, 0, 1, DEVICE_NAME);
263	    if (ret < 0) {
264	        pr_err("%s: failed to allocate device number\n", DEVICE_NAME);
265	        goto err_free_mem;
266	    }
267	
268	    /* 初始化字符设备 */
269	    cdev_init(&cpu_stat_cdev, &cpu_stat_fops);
270	    cpu_stat_cdev.owner = THIS_MODULE;
271	
272	    ret = cdev_add(&cpu_stat_cdev, dev_num, 1);
273	    if (ret < 0) {
274	        pr_err("%s: failed to add cdev\n", DEVICE_NAME);
275	        goto err_unregister;
276	    }
277	
278	    /* 创建设备类 */
279	#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 4, 0)
280	    cpu_stat_class = class_create(CLASS_NAME);
281	#else
282	    cpu_stat_class = class_create(THIS_MODULE, CLASS_NAME);
283	#endif
284	    if (IS_ERR(cpu_stat_class)) {
285	        pr_err("%s: failed to create class\n", DEVICE_NAME);
286	        ret = PTR_ERR(cpu_stat_class);
287	        goto err_cdev_del;
288	    }
289	
290	    /* 创建设备节点 */
291	    cpu_stat_device = device_create(cpu_stat_class, NULL, dev_num, NULL, DEVICE_NAME);
292	    if (IS_ERR(cpu_stat_device)) {
293	        pr_err("%s: failed to create device\n", DEVICE_NAME);
294	        ret = PTR_ERR(cpu_stat_device);
295	        goto err_class_destroy;
296	    }
297	
298	    /* 初始化高精度定时器 */
299	    timer_interval = ktime_set(1, 0);  /* 1 秒 */
300	    hrtimer_init(&update_timer, CLOCK_MONOTONIC, HRTIMER_MODE_REL);
301	    update_timer.function = timer_callback;
302	
303	    /* 首次更新数据 */
304	    update_cpu_stats();
305	
306	    /* 启动定时器 */
307	    hrtimer_start(&update_timer, timer_interval, HRTIMER_MODE_REL);
308	
309	    pr_info("%s: module loaded successfully\n", DEVICE_NAME);
310	    return 0;
311	
312	err_class_destroy:
313	    class_destroy(cpu_stat_class);
314	err_cdev_del:
315	    cdev_del(&cpu_stat_cdev);
316	err_unregister:
317	    unregister_chrdev_region(dev_num, 1);
318	err_free_mem:
319	    free_pages((unsigned long)cpu_stat_data, get_order(data_size));
320	    return ret;
321	}
322	
323	/*
324	 * 模块卸载
325	 */
326	static void __exit cpu_stat_collector_exit(void)
327	{
328	    pr_info("%s: unloading module\n", DEVICE_NAME);
329	
330	    /* 停止定时器 */
331	    hrtimer_cancel(&update_timer);
332	
333	    /* 销毁设备 */
334	    device_destroy(cpu_stat_class, dev_num);
335	    class_destroy(cpu_stat_class);
336	    cdev_del(&cpu_stat_cdev);
337	    unregister_chrdev_region(dev_num, 1);
338	
339	    /* 释放内存 */
340	    free_pages((unsigned long)cpu_stat_data, get_order(data_size));
341	
342	    pr_info("%s: module unloaded\n", DEVICE_NAME);
343	}
344	
345	module_init(cpu_stat_collector_init);
346	module_exit(cpu_stat_collector_exit);
