#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

#include "../kmod/weaknet_kmod_abi.h"

#define MAX_RETRY 1000

static const char *const g_softirq_name[WEAKNET_KMOD_NR_SOFTIRQ] = {
	"HI", "TIMER", "NET_TX", "NET_RX", "BLOCK",
	"IRQ_POLL", "TASKLET", "SCHED", "HRTIMER", "RCU",
};

static void usage(const char *prog)
{
	fprintf(stderr,
		"用法: %s <cpu|softirq> [设备路径] [--count N] [--interval SEC]\n",
		prog);
}

/*
 * 重试直到读到一致快照：前后两次读到的 seq 相同且为偶数。
 * 内存屏障由 __atomic_load_n 的 acquire 语义提供。
 */
static uint64_t snapshot_begin(uint64_t *seq)
{
	uint64_t s;

	do {
		s = __atomic_load_n(seq, __ATOMIC_ACQUIRE);
	} while (s & 1ULL);

	return s;
}

static int snapshot_retry(uint64_t start, uint64_t *seq)
{
	uint64_t end = __atomic_load_n(seq, __ATOMIC_ACQUIRE);

	return start == end && !(end & 1ULL);
}

static int read_snapshot(int fd, void *dst, size_t size, size_t header_off,
			 uint64_t *seq_out)
{
	uint64_t *seq = (uint64_t *)((char *)dst + header_off);
	int tries;

	for (tries = 0; tries < MAX_RETRY; tries++) {
		uint64_t s0 = snapshot_begin(seq);

		/* 直接读共享映射，不拷贝——内核每次写入都会推进 seq */
		if (snapshot_retry(s0, seq)) {
			*seq_out = s0;
			return 0;
		}
	}

	return -1;
}

static uint64_t now_ns(void)
{
	struct timespec ts;

	clock_gettime(CLOCK_MONOTONIC, &ts);
	return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

static double pct(uint64_t part, uint64_t total)
{
	if (!total)
		return 0.0;
	return (double)part * 100.0 / (double)total;
}

struct cpu_delta {
	uint32_t cpu_id;
	unsigned online;
	uint64_t busy;

