						       : 0);
				printf("\n");
			}
			printf("\n");
		}

		memcpy(prev, cur, sizeof(*prev));
		prev_n = n;

		if (iter + 1 < count)
			sleep(interval);
	}

out:
	free(cur);
	free(prev);
	munmap(map, sizeof(struct wn_softirq_snapshot));
	close(fd);
	return 0;
}

int main(int argc, char **argv)
{
	const char *kind, *dev = NULL;
	int count = 1, interval = 1, opt;
	struct option opts[] = {
		{ "count", required_argument, NULL, 'c' },
		{ "interval", required_argument, NULL, 'i' },
		{ "help", no_argument, NULL, 'h' },
		{ NULL, 0, NULL, 0 },
	};

	if (argc < 2) {
		usage(argv[0]);
		return 2;
	}

	kind = argv[1];

	if (argc >= 3 && argv[2][0] != '-')
		dev = argv[2];

	optind = dev ? 3 : 2;
	while ((opt = getopt_long(argc, argv, "c:i:h", opts, NULL)) != -1) {
		switch (opt) {
		case 'c':
			count = atoi(optarg);
			if (count < 1)
				count = 1;
			break;
		case 'i':
			interval = atoi(optarg);
			if (interval < 1)
				interval = 1;
			break;
		case 'h':
			usage(argv[0]);
			return 0;
		default:
			usage(argv[0]);
			return 2;
		}
	}

	if (strcmp(kind, "cpu") == 0)
		return run_cpu(dev ? dev : "/dev/weaknet_cpu_stat", count,
			       interval);
	if (strcmp(kind, "softirq") == 0)
		return run_softirq(dev ? dev : "/dev/weaknet_softirq", count,
				   interval);

	fprintf(stderr, "未知类型: %s\n", kind);
	usage(argv[0]);
	return 2;
}

