			for (i = 0; i < (int)n; i++) {
				const struct wn_cpu_stat *a = &cur->cpu[i];
				const struct wn_cpu_stat *b = &prev->cpu[i];
				uint64_t busy_a, busy_b, tot_a, tot_b;
				uint64_t busy, total;

				busy_a = a->user + a->nice + a->system + a->irq +
					 a->softirq + a->steal;
				busy_b = b->user + b->nice + b->system + b->irq +
					 b->softirq + b->steal;
