// SPDX-License-Identifier: GPL-2.0
/*
 * wn_kmod_read.c - 读取 WeakNet 实验性内核模块共享快照的用户态工具
 *
 * 用法：
 *   wn_kmod_read cpu     [/dev/weaknet_cpu_stat]  [--count N] [--interval SEC]
 *   wn_kmod_read softirq [/dev/weaknet_softirq]   [--count N] [--interval SEC]
 *
 * 读到快照后按 /proc/stat 口径计算每个 CPU 的使用率，并打印。
 * 若给出 --count > 1，则按 --interval 周期重复采样并打印差分。
 *
 * 设计要点：
 *   - seqlock 代次读取：seq 为奇数表示内核正在写入，必须重试
 *   - 使用率计算遵循 ABI 头中的口径：guest/guest_nice 不重复计入 busy
 *   - 离线 CPU 单独标注，不参与平均
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

#include "../weaknet_kmod_abi.h"

#define MAX_RETRY 1000

static const char *const g_softirq_name[WEAKNET_KMOD_NR_SOFTIRQ] = {
	"HI", "TIMER", "NET_TX", "NET_RX", "BLOCK",
	"IRQ_POLL", "TASKLET", "SCHED", "HRTIMER", "RCU",
};

static void usage(const char *prog)
{
	fprintf(stderr,
		"用法: %s <cpu|softirq> [设备路径] [--count N] [--interval SEC]\n",
		prog);
}

/*
 * seqlock 读者：拷贝 -> 校验 -> 不一致重试。
 *
 * 关键点：必须在**拷贝之后**再读一次 seq。若只在拷贝前校验，
 * 内核可能在两次读之间写入，导致拿到半新半旧的数据。
 *
 * 统一使用 32 位访问：内核侧 memcpy 的目的地在用户页，缓存别名
 * 理论上存在，用 32 位访问可避免读到撕裂的 64 位字段。
 * （内核写 seq 用的是 WRITE_ONCE，64 位字段在 5.15/arm64 上原子，
 *  但这里保守处理。）
 */
static uint32_t load_seq(uint64_t *seq)
{
	volatile uint32_t *p = (volatile uint32_t *)seq;

	return __atomic_load_n(p, __ATOMIC_ACQUIRE);
}

static int read_snapshot(void *map, void *dst, size_t size, size_t seq_off,
			 uint64_t *seq_out)
{
	uint64_t *seq = (uint64_t *)((char *)map + seq_off);
	uint32_t s0, s1;
	int tries;

	for (tries = 0; tries < MAX_RETRY; tries++) {
		s0 = load_seq(seq);
		if (s0 & 1u)
			continue;	/* 内核正在写入 */

		memcpy(dst, map, size);

		/* 读屏障：确保 memcpy 完成后再读 seq */
		__atomic_thread_fence(__ATOMIC_ACQUIRE);
		s1 = load_seq(seq);

		if (s0 == s1) {
			*seq_out = s0;
			return 0;
		}
	}

	return -1;
}

static uint64_t now_ns(void)
{
	struct timespec ts;

	clock_gettime(CLOCK_MONOTONIC, &ts);
	return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

/*
 * 交叉校验模块侧时间戳：两者都基于 CLOCK_MONOTONIC，差值应当等于
 * 采样延迟（毫秒级）。若差值为负或大得离谱，说明 ABI 布局对不上。
 */
static void check_sample_age(uint64_t sample_ns, int iter)
{
	uint64_t age_ms;

	if (!sample_ns)
		return;

	age_ms = (now_ns() - sample_ns) / 1000000ULL;

	if (iter == 0)
		printf("快照时延: %" PRIu64 " ms\\n\\n", age_ms);
}

static double pct(uint64_t part, uint64_t total)
{
	if (!total)
		return 0.0;
	return (double)part * 100.0 / (double)total;
}

struct cpu_delta {
	uint32_t cpu_id;
	unsigned online;
	uint64_t busy;
	uint64_t total;
};

static int run_cpu(const char *dev, int count, int interval)
{
	struct wn_cpu_snapshot *cur = NULL, *prev = NULL;
	uint32_t prev_n = 0;
	void *map;
	int fd, i, iter;

	fd = open(dev, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "打开 %s 失败: %s\n", dev, strerror(errno));
		return 1;
	}

	map = mmap(NULL, sizeof(struct wn_cpu_snapshot), PROT_READ,
		   MAP_SHARED, fd, 0);
	if (map == MAP_FAILED) {
		fprintf(stderr, "mmap 失败: %s\n", strerror(errno));
		close(fd);
		return 1;
	}

	cur = calloc(1, sizeof(*cur));
	prev = calloc(1, sizeof(*prev));
	if (!cur || !prev) {
		fprintf(stderr, "内存不足\n");
		goto out;
	}

	for (iter = 0; iter < count; iter++) {
		struct wn_cpu_snapshot *live = (struct wn_cpu_snapshot *)map;
		uint64_t seq = 0;
		uint32_t n;

		if (read_snapshot(live, cur, sizeof(*cur),
				  offsetof(struct wn_cpu_snapshot, hdr.seq),
				  &seq) != 0) {
			fprintf(stderr, "快照重试超限：内核持续写入，放弃\n");
			goto out;
		}

		if (cur->hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
			fprintf(stderr,
				"ABI 版本不匹配：模块=%u 工具=%u\n",
				cur->hdr.abi_version, WEAKNET_KMOD_ABI_VERSION);
			goto out;
		}

		n = cur->hdr.nr_cpus;
		if (n > WEAKNET_KMOD_MAX_CPUS) {
			fprintf(stderr, "nr_cpus 越界: %u\n", n);
			goto out;
		}

		if (iter == 0 || prev_n != n) {
			check_sample_age(cur->hdr.sample_ns, iter);
			printf("=== 累计值（seq=%" PRIu64 "，%u 个 CPU）===\n",
			       seq, n);
			printf("%-4s %-6s %12s %12s %12s %12s\n",
			       "CPU", "online", "user(s)", "system(s)",
			       "idle(s)", "softirq(s)");
			for (i = 0; i < (int)n; i++) {
				const struct wn_cpu_stat *r = &cur->cpu[i];

				printf("%-4u %-6u %12.2f %12.2f %12.2f %12.2f\n",
				       r->cpu_id, r->online,
				       (double)r->user / 1e9,
				       (double)r->system / 1e9,
				       (double)r->idle / 1e9,
				       (double)r->softirq / 1e9);
			}
			printf("\n");
		} else {
			uint64_t t_busy = 0, t_total = 0;

			printf("=== 区间使用率（间隔 %.1fs）===\n",
			       (double)interval);

			for (i = 0; i < (int)n; i++) {
				const struct wn_cpu_stat *a = &cur->cpu[i];
				const struct wn_cpu_stat *b = &prev->cpu[i];
				uint64_t busy_a, busy_b, tot_a, tot_b;
				uint64_t busy, total;

				busy_a = a->user + a->nice + a->system + a->irq +
					 a->softirq + a->steal;
				busy_b = b->user + b->nice + b->system + b->irq +
					 b->softirq + b->steal;
				tot_a = busy_a + a->idle + a->iowait;
				tot_b = busy_b + b->idle + b->iowait;

				if (tot_a <= tot_b)
					continue;

				busy = busy_a - busy_b;
				total = tot_a - tot_b;

				/* 离线 CPU 不参与平均 */
				if (a->online) {
					t_busy += busy;
					t_total += total;
				}

				printf("cpu%-2u %-4s busy=%6.2f%%  "
				       "(Δbusy=%" PRIu64 "ns Δtotal=%" PRIu64 "ns)\n",
				       a->cpu_id,
				       a->online ? "on" : "off",
				       pct(busy, total), busy, total);
			}

			printf("--- 在线 CPU 平均 busy=%.2f%% ---\n\n",
			       pct(t_busy, t_total));
		}

		memcpy(prev, cur, sizeof(*prev));
		prev_n = n;

		if (iter + 1 < count)
			sleep(interval);
	}

out:
	free(cur);
	free(prev);
	munmap(map, sizeof(struct wn_cpu_snapshot));
	close(fd);
	return 0;
}

static int run_softirq(const char *dev, int count, int interval)
{
	struct wn_softirq_snapshot *cur = NULL, *prev = NULL;
	uint32_t prev_n = 0;
	void *map;
	int fd, i, j, iter;

	fd = open(dev, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "打开 %s 失败: %s\n", dev, strerror(errno));
		return 1;
	}

	map = mmap(NULL, sizeof(struct wn_softirq_snapshot), PROT_READ,
		   MAP_SHARED, fd, 0);
	if (map == MAP_FAILED) {
		fprintf(stderr, "mmap 失败: %s\n", strerror(errno));
		close(fd);
		return 1;
	}

	cur = calloc(1, sizeof(*cur));
	prev = calloc(1, sizeof(*prev));
	if (!cur || !prev) {
		fprintf(stderr, "内存不足\n");
		goto out;
	}

	for (iter = 0; iter < count; iter++) {
		struct wn_softirq_snapshot *live =
			(struct wn_softirq_snapshot *)map;
		uint64_t seq = 0;
		uint32_t n;

		if (read_snapshot(live, cur, sizeof(*cur),
				  offsetof(struct wn_softirq_snapshot, hdr.seq),
				  &seq) != 0) {
			fprintf(stderr, "快照重试超限，放弃\n");
			goto out;
		}

		memcpy(cur, live, sizeof(*cur));

		if (cur->hdr.abi_version != WEAKNET_KMOD_ABI_VERSION) {
			fprintf(stderr, "ABI 版本不匹配\n");
			goto out;
		}

		n = cur->hdr.nr_cpus;
		if (n > WEAKNET_KMOD_MAX_CPUS) {
			fprintf(stderr, "nr_cpus 越界: %u\n", n);
			goto out;
		}

		if (iter == 0 || prev_n != n) {
			printf("=== 累计计数（seq=%" PRIu64 "，%u 个 CPU）===\n",
			       seq, n);
			printf("%-4s %-6s", "CPU", "online");
			for (j = 0; j < (int)WEAKNET_KMOD_NR_SOFTIRQ; j++)
				printf(" %10s", g_softirq_name[j]);
			printf("\n");

			for (i = 0; i < (int)n; i++) {
				const struct wn_softirq_stat *r = &cur->cpu[i];

				printf("%-4u %-6u", r->cpu_id, r->online);
				for (j = 0; j < (int)WEAKNET_KMOD_NR_SOFTIRQ; j++)
					printf(" %10" PRIu64, r->cnt[j]);
				printf("\n");
			}
			printf("\n");
		} else {
			printf("=== 区间增量（间隔 %.1fs）===\n",
			       (double)interval);
			printf("%-4s %-6s", "CPU", "online");
			for (j = 0; j < (int)WEAKNET_KMOD_NR_SOFTIRQ; j++)
				printf(" %10s", g_softirq_name[j]);
			printf("\n");

			for (i = 0; i < (int)n; i++) {
				const struct wn_softirq_stat *a = &cur->cpu[i];
				const struct wn_softirq_stat *b = &prev->cpu[i];

				printf("%-4u %-6s", a->cpu_id,
				       a->online ? "on" : "off");
				for (j = 0; j < (int)WEAKNET_KMOD_NR_SOFTIRQ; j++)
					printf(" %10" PRIu64,
					       a->cnt[j] >= b->cnt[j]
						       ? a->cnt[j] - b->cnt[j]
						       : 0);
				printf("\n");
			}
			printf("\n");
		}

		memcpy(prev, cur, sizeof(*prev));
		prev_n = n;

		if (iter + 1 < count)
			sleep(interval);
	}

out:
	free(cur);
	free(prev);
	munmap(map, sizeof(struct wn_softirq_snapshot));
	close(fd);
	return 0;
}

int main(int argc, char **argv)
{
	const char *kind, *dev = NULL;
	int count = 1, interval = 1, opt;
	struct option opts[] = {
		{ "count", required_argument, NULL, 'c' },
		{ "interval", required_argument, NULL, 'i' },
		{ "help", no_argument, NULL, 'h' },
		{ NULL, 0, NULL, 0 },
	};

	if (argc < 2) {
		usage(argv[0]);
		return 2;
	}

	kind = argv[1];

	if (argc >= 3 && argv[2][0] != '-')
		dev = argv[2];

	optind = dev ? 3 : 2;
	while ((opt = getopt_long(argc, argv, "c:i:h", opts, NULL)) != -1) {
		switch (opt) {
		case 'c':
			count = atoi(optarg);
			if (count < 1)
				count = 1;
			break;
		case 'i':
			interval = atoi(optarg);
			if (interval < 1)
				interval = 1;
			break;
		case 'h':
			usage(argv[0]);
			return 0;
		default:
			usage(argv[0]);
			return 2;
		}
	}

	if (strcmp(kind, "cpu") == 0)
		return run_cpu(dev ? dev : "/dev/weaknet_cpu_stat", count,
			       interval);
	if (strcmp(kind, "softirq") == 0)
		return run_softirq(dev ? dev : "/dev/weaknet_softirq", count,
				   interval);

	fprintf(stderr, "未知类型: %s\n", kind);
	usage(argv[0]);
	return 2;
}

/* SPDX-License-Identifier: GPL-2.0 */
/*
 * weaknet_kmod_abi.h - WeakNet 实验性内核模块与用户态共享的 ABI 定义
 *
 * 本头文件同时被内核模块和用户态工具包含，因此必须保持纯数据结构，
 * 不得引入任一侧专有的头文件。
 *
 * ABI 版本变更规则：只要下面的结构体布局发生变化，必须递增
 * WEAKNET_KMOD_ABI_VERSION，用户态工具据此拒绝读取不兼容的模块。
 */
#ifndef WEAKNET_KMOD_ABI_H
#define WEAKNET_KMOD_ABI_H

#ifdef __KERNEL__
#include <linux/types.h>
#define WN_U64 __u64
#define WN_U32 __u32
#else
#include <stdint.h>
/*
 * 用户态不引入 <linux/types.h>：它可能与 <sys/stat.h> 间接引入的
 * asm-generic/int-ll64.h 产生 typedef 冲突。统一使用定宽类型。
 */
#define WN_U64 uint64_t
#define WN_U32 uint32_t
#endif

#define WEAKNET_KMOD_ABI_VERSION 1u
#define WEAKNET_KMOD_MAX_CPUS    256u
#define WEAKNET_KMOD_NR_SOFTIRQ  10u

/*
 * 快照头。seq 为 seqlock 代次号：
 *   奇数 = 内核正在写入，读者必须重试
 *   偶数 = 内容一致，可以采信
 *
 * 读者流程：
 *   判断 seq 为偶数 -> 拷贝整份快照 -> 再读一次 seq -> 两次相同才采信
 *
 * 内核侧的写入窗口被压缩到一次 memcpy（8 核约 700 字节），
 * 因此用户态重试概率极低。
 */
struct wn_kmod_hdr {
	WN_U64 seq;
	WN_U64 sample_ns;   /* 本次采集的 CLOCK_MONOTONIC 时间戳（纳秒） */
	WN_U32 abi_version;
	WN_U32 nr_cpus;     /* 有效记录条数，<= WEAKNET_KMOD_MAX_CPUS */
};

/*
 * 单 CPU 累计时间，单位是纳秒（不是 jiffies）。
 *
 * 语义与 /proc/stat 一致：user 已包含 guest，nice 已包含 guest_nice。
 * 计算使用率时应当为：
 *
 *   busy  = user + nice + system + irq + softirq + steal
 *   total = busy + idle + iowait
 *
 * 不要把 guest / guest_nice 再加进 busy，否则会重复计入。
 */
struct wn_cpu_stat {
	WN_U32 cpu_id;
	WN_U32 online;
	WN_U64 user;
	WN_U64 nice;
	WN_U64 system;
	WN_U64 idle;
	WN_U64 iowait;
	WN_U64 irq;
	WN_U64 softirq;
	WN_U64 steal;
	WN_U64 guest;
	WN_U64 guest_nice;
};

struct wn_cpu_snapshot {
	struct wn_kmod_hdr hdr;
	struct wn_cpu_stat cpu[WEAKNET_KMOD_MAX_CPUS];
};

/*
 * 单 CPU 软中断累计触发次数。cnt[] 索引与内核 enum 一致：
 *   0 HI, 1 TIMER, 2 NET_TX, 3 NET_RX, 4 BLOCK,
 *   5 IRQ_POLL, 6 TASKLET, 7 SCHED, 8 HRTIMER, 9 RCU
 */
struct wn_softirq_stat {
	WN_U32 cpu_id;
	WN_U32 online;
	WN_U64 cnt[WEAKNET_KMOD_NR_SOFTIRQ];
};

struct wn_softirq_snapshot {
	struct wn_kmod_hdr hdr;
	struct wn_softirq_stat cpu[WEAKNET_KMOD_MAX_CPUS];
};

#endif /* WEAKNET_KMOD_ABI_H */

// SPDX-License-Identifier: GPL-2.0
/*
 * weaknet_softirq.c - WeakNet 实验性软中断计数采集内核模块
 *
 * 定位：B1 实验路径，与 weaknet_cpu_stat 同构。
 *
 * 数据通路：
 *   hrtimer(1s) -> 逐 CPU 读取 kstat_softirqs_cpu 到私有缓冲区
 *              -> seqlock 保护下 memcpy 到共享缓冲区
 *              -> 用户态 mmap 只读访问
 *
 * 相比之下少一个 tickless 细节：软中断计数是纯递增次数，
 * 没有 idle / iowait 那种需要走 tick 子系统的特殊路径。
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/device.h>
#include <linux/mm.h>
#include <linux/vmalloc.h>
#include <linux/hrtimer.h>
#include <linux/ktime.h>
#include <linux/kernel_stat.h>
#include <linux/interrupt.h>
#include <linux/cpumask.h>
#include <linux/version.h>
#include <linux/capability.h>
#include <linux/sched.h>

#include "weaknet_kmod_abi.h"

#define DEVICE_NAME "weaknet_softirq"
#define CLASS_NAME  DEVICE_NAME

MODULE_LICENSE("GPL");
MODULE_AUTHOR("tanqf");
MODULE_DESCRIPTION("WeakNet experimental softirq counter collector via mmap");
MODULE_VERSION("0.1.0");

static dev_t g_dev;
static struct cdev g_cdev;
static struct class *g_class;
static struct device *g_device;

static struct wn_softirq_snapshot *g_shared;
static struct wn_softirq_snapshot *g_priv;
static size_t g_map_size;

static struct hrtimer g_timer;
static ktime_t g_interval;

static void wn_collect(struct wn_softirq_snapshot *priv)
{
	int cpu, n = 0;

	priv->hdr.abi_version = WEAKNET_KMOD_ABI_VERSION;
	priv->hdr.sample_ns = ktime_get_ns();

	for_each_possible_cpu(cpu) {
		struct wn_softirq_stat *r;
		int i;

		if (n >= (int)WEAKNET_KMOD_MAX_CPUS)
			break;

		r = &priv->cpu[n++];
		r->cpu_id = (u32)cpu;
		r->online = cpu_online(cpu) ? 1u : 0u;

		for (i = 0; i < (int)WEAKNET_KMOD_NR_SOFTIRQ; i++)
			r->cnt[i] = kstat_softirqs_cpu(i, cpu);
	}

	priv->hdr.nr_cpus = (u32)n;
}

static void wn_publish(struct wn_softirq_snapshot *dst,
		       const struct wn_softirq_snapshot *src)
{
	u64 s = READ_ONCE(dst->hdr.seq);
	size_t bytes = src->hdr.nr_cpus * sizeof(struct wn_softirq_stat);

	WRITE_ONCE(dst->hdr.seq, s + 1);
	smp_wmb();

	dst->hdr.abi_version = src->hdr.abi_version;
	dst->hdr.sample_ns = src->hdr.sample_ns;
	dst->hdr.nr_cpus = src->hdr.nr_cpus;
	memcpy(dst->cpu, src->cpu, bytes);

	smp_wmb();
	WRITE_ONCE(dst->hdr.seq, s + 2);
}

static enum hrtimer_restart wn_timer_cb(struct hrtimer *t)
{
	wn_collect(g_priv);
	wn_publish(g_shared, g_priv);

	hrtimer_forward_now(t, g_interval);
	return HRTIMER_RESTART;
}

static int wn_open(struct inode *inode, struct file *file)
{
	if (!capable(CAP_SYS_ADMIN))
		return -EPERM;
	return 0;
}

static void wn_vma_close(struct vm_area_struct *vma)
{
	module_put(THIS_MODULE);
}

static const struct vm_operations_struct wn_vm_ops = {
	.close = wn_vma_close,
};

static int wn_mmap(struct file *file, struct vm_area_struct *vma)
{
	unsigned long size = vma->vm_end - vma->vm_start;
	int ret;

	if (vma->vm_pgoff)
		return -EINVAL;

	if (size > g_map_size) {
		pr_err("%s: mmap size %lu exceeds %zu\n",
		       DEVICE_NAME, size, g_map_size);
		return -EINVAL;
	}

	if (!try_module_get(THIS_MODULE))
		return -ENODEV;

	ret = remap_vmalloc_range(vma, g_shared, 0);
	if (ret) {
		module_put(THIS_MODULE);
		return ret;
	}

	vma->vm_ops = &wn_vm_ops;
	return 0;
}

static const struct file_operations wn_fops = {
	.owner  = THIS_MODULE,
	.open   = wn_open,
	.mmap   = wn_mmap,
	.llseek = no_llseek,
};

static int __init wn_init(void)
{
	int ret;

	BUILD_BUG_ON(NR_SOFTIRQS != WEAKNET_KMOD_NR_SOFTIRQ);
	BUILD_BUG_ON(sizeof(struct wn_softirq_stat) % 8);

	g_map_size = PAGE_ALIGN(sizeof(struct wn_softirq_snapshot));

	g_shared = vmalloc_user(g_map_size);
	if (!g_shared)
		return -ENOMEM;

	g_priv = vmalloc(g_map_size);
	if (!g_priv) {
		ret = -ENOMEM;
		goto err_free_shared;
	}

	memset(g_priv, 0, g_map_size);
	memset(g_shared, 0, g_map_size);

	wn_collect(g_priv);
	wn_publish(g_shared, g_priv);

	ret = alloc_chrdev_region(&g_dev, 0, 1, DEVICE_NAME);
	if (ret)
		goto err_free_priv;

	cdev_init(&g_cdev, &wn_fops);
	g_cdev.owner = THIS_MODULE;

	ret = cdev_add(&g_cdev, g_dev, 1);
	if (ret)
		goto err_unregister;

#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 4, 0)
	g_class = class_create(CLASS_NAME);
#else
	g_class = class_create(THIS_MODULE, CLASS_NAME);
#endif
	if (IS_ERR(g_class)) {
		ret = PTR_ERR(g_class);
		goto err_cdev_del;
	}

	g_device = device_create(g_class, NULL, g_dev, NULL, DEVICE_NAME);
	if (IS_ERR(g_device)) {
		ret = PTR_ERR(g_device);
		goto err_class_destroy;
	}

	g_interval = ktime_set(1, 0);
	hrtimer_init(&g_timer, CLOCK_MONOTONIC, HRTIMER_MODE_REL);
	g_timer.function = wn_timer_cb;
	hrtimer_start(&g_timer, g_interval, HRTIMER_MODE_REL);

	pr_info("%s: loaded, %d possible CPUs, map %zu bytes\n",
		DEVICE_NAME, num_possible_cpus(), g_map_size);
	return 0;

err_class_destroy:
	class_destroy(g_class);
err_cdev_del:
	cdev_del(&g_cdev);
err_unregister:
	unregister_chrdev_region(g_dev, 1);
err_free_priv:
	vfree(g_priv);
err_free_shared:
	vfree(g_shared);
	return ret;
}

static void __exit wn_exit(void)
{
	hrtimer_cancel(&g_timer);

	device_destroy(g_class, g_dev);
	class_destroy(g_class);
	cdev_del(&g_cdev);
	unregister_chrdev_region(g_dev, 1);

	vfree(g_priv);
	vfree(g_shared);

	pr_info("%s: unloaded\n", DEVICE_NAME);
}

module_init(wn_init);
module_exit(wn_exit);

