		}

		memcpy(prev, cur, sizeof(*prev));
		prev_n = n;

		if (iter + 1 < count)
			sleep(interval);
	}

out:
	free(cur);
	free(prev);
	munmap(map, sizeof(struct wn_cpu_snapshot));
	close(fd);
	return 0;
