static u64 cpu_stat_get_idle_time(int cpu)
{
    u64 idle_time = -1ULL;

    /* 尝试获取精确的空闲时间（考虑 tickless 模式） */
    idle_time = get_cpu_idle_time_us(cpu, NULL);

    if (idle_time == -1ULL) {
