        idle_time = kcpustat_cpu(cpu).cpustat[CPUTIME_IDLE];
        idle_time = nsec_to_jiffies(idle_time);
    } else {
        /* 转换微秒到 clock_t */
        idle_time = usecs_to_jiffies(idle_time);
    }

    return idle_time;
}

