timeout 120 ssh board 'bash -s' <<'EOF'
echo "=== seqlock 回归：15s 高频读取 ==="
sudo python3 - <<'PY'
import mmap, os, struct, time
MAXCPU=256
HDR=struct.Struct("<QQII")
CPU=struct.Struct("<IIQQQQQQQQQQ")
total=HDR.size+MAXCPU*CPU.size
TICK=4_000_000

fd=os.open("/dev/weaknet_cpu_stat", os.O_RDONLY)
mm=mmap.mmap(fd, total, prot=mmap.PROT_READ)
mv=memoryview(mm)

def snapshot():
    for _ in range(200000):
        seq, ns, abi, n = HDR.unpack_from(mm, 0)
        if seq & 1: continue
        blob = bytes(mv[0:total])
        if HDR.unpack_from(blob,0)[0] == seq:
            return seq, ns, abi, n, blob
    raise RuntimeError("retry exhausted")

ok=0; fail=0; tears=[]; prev={}
t0=time.time()
while time.time() - t0 < 15:
    try:
        seq, ns, abi, n, blob = snapshot()
    except RuntimeError:
        fail += 1; continue
    ok += 1
    for i in range(n):
        rec = CPU.unpack_from(blob, HDR.size + i*CPU.size)
        cid = rec[0]; vals = rec[2:]
        for k in (0,1,2,5,6,7,8,9):
            if vals[k] % TICK:
                tears.append(("grain", seq, cid, k, vals[k]))
        if cid in prev:
            for k in range(10):
                if vals[k] < prev[cid][k]:
                    tears.append(("mono", seq, cid, k))
        prev[cid]=vals
dt=time.time()-t0
print("采样 %d 次，重试耗尽 %d，%.0f 次/秒，耗时 %.1fs" % (ok, fail, ok/dt, dt))
print("违规 = %d" % len(tears))
for t in tears[:5]: print("  !!", t)
mv.release(); mm.close(); os.close(fd)
PY
EOF

