		return kcpustat_cpu(cpu).cpustat[CPUTIME_IOWAIT];

	us = get_cpu_iowait_time_us(cpu, NULL);
	if (us != (u64)-1)
		return us * NSEC_PER_USEC_LOCAL;
	return kcpustat_cpu(cpu).cpustat[CPUTIME_IOWAIT];
}

