	WN_U64 seq;
	WN_U64 sample_ns;   /* 本次采集的 CLOCK_MONOTONIC 时间戳（纳秒） */
	WN_U32 abi_version;
	WN_U32 nr_cpus;     /* 有效记录条数，<= WEAKNET_KMOD_MAX_CPUS */
