160	 * @stat_unknown:   中断里判不出源的次数
161	 * @stat_unmatched: 有电压但匹配不到任何键的次数
162	 * @last_raw:   最近一次读到的 DATA0 原始值
163	 * @last_mv:    最近一次换算出的电压
164	 * @dbg_dir:    debugfs 目录
165	 */
166	struct wn_lradc {
167		struct device *dev;
168		void __iomem *base;
169		struct clk *clk;
170		struct reset_control *rst;
171		int irq;
172		u32 vref_mv;
173	
174		struct wn_lradc_key keys[LRADC_MAX_KEYS];
175		u32 nr_keys;
176	
177		spinlock_t lock;
178		u32 cur_keycode;
179	
180		bool is_open;
181	
182		u64 stat_irq;
183		u64 stat_keydown;
184		u64 stat_keyup;
185		u64 stat_unknown;
186		u64 stat_unmatched;
187		u32 last_raw;
188		u32 last_mv;
189	
190		struct dentry *dbg_dir;
191	};
192	
193	/* ------------------------------------------------------------------ */
194	/* 寄存器访问                                                          */
195	/* ------------------------------------------------------------------ */
196	
197	static inline u32 wn_lradc_read(struct wn_lradc *lradc, u32 reg)
198	{
199		return readl(lradc->base + reg);
200	}
201	
202	static inline void wn_lradc_write(struct wn_lradc *lradc, u32 reg, u32 val)
203	{
204		writel(val, lradc->base + reg);
205	}
206	
207	/*
208	 * 6bit 原始码 → 毫伏。
209	 * 与 mainline 的 val * vref / 63 等价，只是把顺序改成先乘后除以免整数截断。
210	 */
211	static u32 wn_lradc_raw_to_mv(struct wn_lradc *lradc, u32 raw)
212	{
213		return raw * lradc->vref_mv / LRADC_FULL_SCALE;
214	}
215	
216	/*
217	 * 在按键表里找与实测电压最接近的一项。
218	 * 返回键索引，找不到返回 -ENOENT。
219	 *
220	 * 语义与 mainline 一致：取绝对差最小者，而不是区间判定。
221	 * 这样 DT 里标的电压有偏差也不会整键失效。
222	 */
223	static int wn_lradc_match_key(struct wn_lradc *lradc, u32 mv, u32 *out_keycode)
224	{
225		u32 i, best_diff = U32_MAX;
226		int best = -ENOENT;
227	
228		for (i = 0; i < lradc->nr_keys; i++) {
229			u32 diff = abs((int)lradc->keys[i].voltage_mv - (int)mv);
230	
231			if (diff < best_diff) {
232				best_diff = diff;
233				best = (int)i;
234			}
235		}
236	
237		if (best >= 0 && out_keycode)
238			*out_keycode = lradc->keys[best].keycode;
239	
240		return best;
241	}
242	
243	/* ------------------------------------------------------------------ */
244	/* 中断处理                                                            */
245	/* ------------------------------------------------------------------ */
246	
247	/*
248	 * 中断上下文约束（驱动开发必考点）：
249	 *   - 不能睡眠：不能调用 kmalloc(GFP_KERNEL)、mutex_lock、copy_to_user 等
250	 *   - 不能做长耗时操作
251	 *   本 handler 只做 readl/writel + 内存写，完全满足。
252	 *
253	 * 共享状态的保护：
254	 *   @cur_keycode 会被这里的「中断上下文」与 debugfs 的「进程上下文」同时读，
255	 *   所以用 spinlock 而非 mutex（mutex 不能用在中断里）。
256	 */
257	static irqreturn_t wn_lradc_irq(int irq, void *dev_id)
258	{
259		struct wn_lradc *lradc = dev_id;
260		unsigned long flags;
261		u32 ints, raw, mv, keycode = 0;
262		bool reported = false;
263	
264		/* 先读中断状态；判不出源就直接返回 IRQ_NONE，让内核统计 spurious */
265		ints = wn_lradc_read(lradc, LRADC_INTS);
266		if (!(ints & (CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ |
267			      CHAN0_HOLD_IRQ | CHAN0_ALRDY_HOLD_IRQ |
268			      CHAN0_DATA_IRQ))) {
269			spin_lock_irqsave(&lradc->lock, flags);
270			lradc->stat_unknown++;
271			lradc->stat_irq++;
272			spin_unlock_irqrestore(&lradc->lock, flags);
273			return IRQ_NONE;
274		}
275	
276		spin_lock_irqsave(&lradc->lock, flags);
277		lradc->stat_irq++;
278		spin_unlock_irqrestore(&lradc->lock, flags);
279	
280		/* 抬起：上报 release 并清掉缓存键码 */
281		if (ints & CHAN0_KEYUP_IRQ) {
282			spin_lock_irqsave(&lradc->lock, flags);
283			keycode = lradc->cur_keycode;
284			lradc->cur_keycode = 0;
285			lradc->stat_keyup++;
286			spin_unlock_irqrestore(&lradc->lock, flags);
287	
288			if (keycode)
289				dev_info(lradc->dev, "key release code=%u\n", keycode);
290			reported = true;
291		}
292	
293		/* 按下：只有在当前无键时才处理，避免重复触发把同一键反复上报 */
294		if ((ints & CHAN0_KEYDOWN_IRQ)) {
295			bool idle;
296	
297			spin_lock_irqsave(&lradc->lock, flags);
298			idle = (lradc->cur_keycode == 0);
299			spin_unlock_irqrestore(&lradc->lock, flags);
300	
301			if (idle) {
302				int idx;
303	
304				raw = wn_lradc_read(lradc, LRADC_DATA0) & LRADC_DATA_MASK;
305				mv = wn_lradc_raw_to_mv(lradc, raw);
306				idx = wn_lradc_match_key(lradc, mv, &keycode);
307	
308				spin_lock_irqsave(&lradc->lock, flags);
309				lradc->last_raw = raw;
310				lradc->last_mv = mv;
311				if (idx < 0) {
312					lradc->stat_unmatched++;
313					keycode = 0;
314				} else {
315					lradc->cur_keycode = keycode;
316					lradc->stat_keydown++;
317				}
318				spin_unlock_irqrestore(&lradc->lock, flags);
319	
320				if (idx < 0)
321					dev_info(lradc->dev,
322						 "keydown raw=%u mv=%u -> no matching key\n",
323						 raw, mv);
324				else
325					dev_info(lradc->dev,
326						 "key press code=%u (raw=%u mv=%u key#%d)\n",
327						 keycode, raw, mv, idx);
328				reported = true;
329			}
330		}
331	
332		/* 写 1 清中断状态位（W1C）。必须在处理完之后清，否则会丢事件 */
333		wn_lradc_write(lradc, LRADC_INTS, ints);
334	
335		/* 有 DATA/HOLD 类中断但没产生按键事件时也返回 HANDLED，因为我们确实消费了它 */
336		return (reported || ints) ? IRQ_HANDLED : IRQ_NONE;
337	}
338	
339	/* ------------------------------------------------------------------ */
340	/* ADC 使能 / 关闭                                                     */
341	/* ------------------------------------------------------------------ */
342	
343	/*
344	 * 使能 ADC。
345	 *
346	 * 寄存器取值与 mainline 一致：
347	 *   FIRST_CONVERT_DLY(2)  首次转换延时
348	 *   LEVELA_B_CNT(1)       电平判决次数
349	 *   HOLD_EN(1)            按住不放时重复上报
350	 *   SAMPLE_RATE(0)        250 Hz / 4 ms
351	 *   ENABLE(1)
352	 *
353	 * 注意：本板实测初始 CTRL=0x01000168，其中 FIRST_CONVERT_DLY 为 1 而非 2，
354	 * 且 ENABLE=0。这里按 mainline 的 2 写入，probe 后会把实测值打到日志里，
355	 * 便于对照「我确实改动了硬件」。
356	 */
357	static int wn_lradc_enable(struct wn_lradc *lradc)
358	{
359		int ret;
360	
361		ret = clk_prepare_enable(lradc->clk);
362		if (ret) {
363			dev_err(lradc->dev, "clk_prepare_enable failed: %d\n", ret);
364			return ret;
365		}
366	
367		wn_lradc_write(lradc, LRADC_CTRL,
368			       FIRST_CONVERT_DLY(2) | LEVELA_B_CNT(1) | HOLD_EN(1) |
369			       SAMPLE_RATE(LRADC_SAMPLE_RATE_VAL) | ENABLE(1));
370		wn_lradc_write(lradc, LRADC_INTC, CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ);
371	
372		lradc->is_open = true;
373		return 0;
374	}
375	
376	static void wn_lradc_disable(struct wn_lradc *lradc)
377	{
378		/* 关中断使能，再关 ADC，最后关时钟。顺序反了会留下挂起中断 */
379		wn_lradc_write(lradc, LRADC_INTC, 0);
380		wn_lradc_write(lradc, LRADC_CTRL,
381			       FIRST_CONVERT_DLY(2) | LEVELA_B_CNT(1) | HOLD_EN(1) |
382			       SAMPLE_RATE(2));	/* ENABLE(0) */
383		clk_disable_unprepare(lradc->clk);
384		lradc->is_open = false;
385	}
386	
387	/* ------------------------------------------------------------------ */
388	/* DT 解析                                                             */
389	/* ------------------------------------------------------------------ */
390	
391	/*
392	 * 从 compatible 字符串里取参考电压，形如 "allwinner,keyboard_1350mv"。
393	 * 取不到就返回默认值。这是本板 BSP 的私有约定，mainline 没有。
394	 */
395	static u32 wn_lradc_parse_vref(struct device *dev)
396	{
397		const char *compat;
398		u32 mv = LRADC_DEFAULT_VREF_MV;
399		int ret;
400	
